/* HireStepX — Programmatic SEO source-of-truth
 *
 * Single source for the auto-generated company × focus landing pages.
 * Each tuple becomes one indexable URL like
 *   /companies/razorpay/pm-interview-questions
 * with content templated from the curated question bank + role-aware
 * sample answers.
 *
 * The strategy: don't try to outrank AmbitionBox / Glassdoor on
 * generic queries ("razorpay interview questions"). Own the long-tail
 * intent layer they underserve — "razorpay PM case study practice",
 * "tcs ninja interview practice 2026 freshers" — where the searcher
 * wants to PRACTICE answering, not just see a list.
 *
 * Curation rules:
 *   - Only (company × focus) tuples with ≥3 entries in the curated
 *     question bank get a page. Thin pages get penalized by Google's
 *     Helpful Content update.
 *   - Each combo carries a hand-written intro paragraph + a hand-
 *     picked framework hint. Auto-generated boilerplate WILL get
 *     deindexed.
 *   - Page slugs use kebab-case. Companies normalised to lowercase.
 */

import type { CompanyKey, FocusArea, RoleFamily } from "./interview-question-bank";

export interface SeoPage {
  /* URL path under /companies/. Generated, not user-editable. */
  slug: string;
  /* What a real candidate would search to land on this page. The H1
     of the rendered page mirrors this query. */
  searchPhrase: string;
  /* Page-specific company. */
  company: CompanyKey;
  /* Optional role-family scope. When undefined, page covers the focus
     across all roles at the company (broader, less competitive). */
  roleFamily?: RoleFamily;
  /* The interview-focus area the page is built around. */
  focus: FocusArea;
  /* Hand-written intro paragraph — distinguishes this page from a
     templated generic one. Avoids the Helpful Content penalty. */
  intro: string;
  /* Framework name + one-line summary, surfaced inline. */
  framework: { name: string; summary: string };
  /* Keywords for the meta description. Mostly informational; Next's
     metadata API doesn't weight these any more, but they pair well
     with OG descriptions. */
  metaKeywords: string[];
  /* Optional priority hint for sitemap.xml — top-tier pages get
     higher priority (0.8), niche combos lower (0.4). */
  sitemapPriority?: number;
  /* Optional ordered steps in the company's hiring process.
     Rendered as a numbered list under "Recruitment Process". */
  recruitmentSteps?: string[];
  /* Optional descriptions of each interview round at this company.
     Rendered as a numbered list under "Interview Rounds". */
  interviewRounds?: string[];
  /* Optional extra Q&A pairs for FAQ schema depth.
     Content MUST be sourced from the codebase (intro, framework, known facts)
    : never invented. Each answer is a plain-text summary (≤300 chars). */
  faqExtra?: Array<{ q: string; a: string }>;
}

